def start_withp(words):
    """Return the first two words from a list of strings that start with 'p'."""
    found = []
    for text in words:
        for word in text.split():
            if word.lower().startswith('p'):
                found.append(word)
                if len(found) == 2:
                    return tuple(found)
    return tuple(found)
```

